import {countries,subjects,malaysia,oecd,format,signed} from './data.js';
export function closestCountries(list,subject){const eligible=list.filter(c=>c.code!=='MYS'&&c[subject]!=null);if(!eligible.length)return [];const gap=Math.min(...eligible.map(c=>Math.abs(c[subject]-malaysia[subject])));return eligible.filter(c=>Math.abs(c[subject]-malaysia[subject])===gap).map(c=>c.code);}
export function setupComparison({travel,goCourtyard}){
 const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const collected=new Set(['MYS']),selected=new Set(['MYS']),explored=new Set();let subject='science',mode='score',predict=true,guess=null,revealed=false,reveals=0;
 const seen=new Set(),guessMode=()=>$('learning-mode').value==='guess';
 const dialog=$('comparison-dialog'),list=()=>[...selected].map(code=>countries.find(c=>c.code===code));
 function open(){for(const d of document.querySelectorAll('dialog[open]'))d.close();render();dialog.showModal();}
 function resetPrediction(){predict=guessMode();guess=null;revealed=false;}
 function tray(){$('card-count').textContent=`${selected.size} ${selected.size===1?"card":"cards"}`;$('card-tray').innerHTML=[...selected].map(code=>{const c=countries.find(c=>c.code===code);return `<span>${esc(c.name)}${code==='MYS'?' · pinned':` <button data-remove="${code}" aria-label="Remove ${esc(c.name)}">×</button>`}</span>`;}).join('');}
 function render(){
  const entries=list(),eligible=entries.filter(c=>c.code!=='MYS'&&c[subject]!=null),hide=predict&&!revealed;
  if(entries.length>1&&!hide)explored.add(subject);
  $('game-subject').innerHTML=Object.entries(subjects).map(([s,n])=>`<option value="${s}" ${s===subject?'selected':''}>${n}</option>`).join('');$('game-mode').value=mode;
  $('game-cards').innerHTML=[...collected].map(code=>{const c=countries.find(c=>c.code===code);return `<button data-toggle="${code}" aria-pressed="${selected.has(code)}" ${code==='MYS'?'disabled':''}>${esc(c.name)}${code==='MYS'?' · pinned':selected.has(code)?' ✓':' +'}</button>`;}).join('');
  $('game-capacity').textContent=`${selected.size-1} / 3 comparison slots. Visit pavilions to collect more cards. Progress lasts for this visit.`;
  $('prediction-start').hidden=!guessMode()||!revealed;$('prediction-start').disabled=eligible.length<2;$('prediction-start').textContent='Try again (practice)';$('game-mode').disabled=guessMode();
  $('prediction').innerHTML=predict&&eligible.length>=2?`${eligible.some(c=>seen.has(c.code+':'+subject))?'<p class="muted">Practice round: you have already viewed some of these scores during this visit.</p>':''}<h3>Which selected country has a ${subjects[subject].toLowerCase()} score closest to Malaysia?</h3><div class="guess-options">${eligible.map(c=>`<button data-guess="${c.code}" ${revealed?'disabled':''} aria-pressed="${guess===c.code}">${esc(c.name)}</button>`).join('')}</div>${revealed?`<p><b>${closestCountries(entries,subject).includes(guess)?'Correct.':'Here is what the numbers show.'}</b> ${closestCountries(entries,subject).map(code=>esc(countries.find(c=>c.code===code).name)).join(' and ')} ${closestCountries(entries,subject).length>1?'are tied as the closest':'is closest'} by rounded mean score. This does not establish statistical equivalence.</p>`:`<button id="reveal-answer" ${guess?'':'disabled'}>Reveal the evidence ↓</button>`}`:'<p class="muted">Choose Guess first in Play style, then select Malaysia and at least two other collected countries with verified scores. Scores stay hidden until you guess and reveal.</p>';
  $('evidence').hidden=hide;
  const values=entries.map(c=>mode==='score'?c[subject]:c.changes[subject]??null),range=Math.max(1,...values.filter(v=>v!=null).map(Math.abs));
  $('game-bars').innerHTML=hide?'':entries.map((c,i)=>{const n=values[i],change=mode==='change',negative=n<0;const width=n==null?0:change?Math.abs(n)/range*50:n/650*100;return `<div class="comparison-row"><div><strong>${esc(c.name)}${c.caution?'*':''}</strong><b>${n==null?'Not available':change?signed(n):n}</b></div><div class="comparison-track ${change?'diverging':''}">${n==null?'':`<i style="width:${width}%;left:${change?(negative?50-width:50):0}%;background:${c.code==='MYS'?'#ba8f41':negative?'#b56842':'#398679'}"></i>`}</div><p>${n==null?'No verified value in this snapshot.':change?(c.ns.includes(subject)?'Change not statistically significant.':'Reported change; consult the OECD source for interpretation.'):`${signed(n-malaysia[subject])} vs Malaysia · ${signed(n-oecd[subject])} vs OECD`}</p><a href="${mode==='score'&&(subject==='science'||subject==='digital'||c.code==='BSZ')?c.source:c.profile}" target="_blank" rel="noopener">OECD evidence ↗</a></div>`;}).join('');
  $('game-table').innerHTML=hide||guessMode()?'':`<thead><tr><th>Country</th>${Object.values(subjects).map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${entries.map(c=>`<tr><th>${esc(c.name)}</th>${Object.keys(subjects).map(s=>`<td>${format(c[s])}</td>`).join('')}</tr>`).join('')}</tbody>`;
  if(!hide)entries.forEach(c=>{seen.add(c.code+':'+subject);if(!guessMode())Object.keys(subjects).forEach(s=>seen.add(c.code+':'+s));});
  $('game-badges').textContent=[selected.size>=3?'✓ Compared three countries':'○ Compare three countries',explored.size>=3?'✓ Explored three subjects':'○ Explore three subjects',reveals?'✓ Revealed the evidence':'○ Complete a prediction'].join(' · ');tray();
 }
 $('learning-mode').addEventListener('change',()=>{mode='score';resetPrediction();});
 $('courtyard-open').onclick=()=>goCourtyard(open);$('game-subject').onchange=e=>{subject=e.target.value;resetPrediction();render();};$('game-mode').onchange=e=>{mode=e.target.value;resetPrediction();render();};
 $('game-cards').onclick=e=>{const code=e.target.closest('[data-toggle]')?.dataset.toggle;if(!code||code==='MYS')return;if(selected.has(code))selected.delete(code);else if(selected.size<4)selected.add(code);else{$('game-capacity').textContent='All three slots are full. Deselect a country card before adding another.';return;}resetPrediction();render();};
 $('card-tray').onclick=e=>{const code=e.target.closest('[data-remove]')?.dataset.remove;if(code){selected.delete(code);resetPrediction();render();}};
 $('prediction-start').onclick=()=>{predict=true;guess=null;revealed=false;render();};$('prediction').onclick=e=>{const code=e.target.closest('[data-guess]')?.dataset.guess;if(code&&!revealed){guess=code;render();}if(e.target.id==='reveal-answer'&&guess){revealed=true;reveals++;render();}};
 $('reset-comparison').onclick=()=>{selected.clear();selected.add('MYS');subject='science';mode='score';resetPrediction();render();$('game-capacity').textContent='Comparison reset. Malaysia is pinned. Your collected cards and discoveries are still available.';};
 $('collect-more').onclick=()=>{dialog.close();$('directory-open').click();};
 document.addEventListener('pisa-visit',e=>{const c=countries.find(c=>c.code===e.detail);if(!c)return;if(!guessMode())seen.add(c.code+':'+document.querySelector('[data-subject][aria-pressed="true"]').dataset.subject);collected.add(c.code);if(selected.size<4)selected.add(c.code);resetPrediction();tray();const content=$('country-content');const panel=document.createElement('div');panel.className='collected-card';panel.innerHTML=`<strong>✓ ${esc(c.name)} card collected</strong><p>${selected.has(c.code)?'Added to your comparison tray.':'Your tray is full. Swap cards in the courtyard.'}</p><button>Compare in the courtyard ↗</button>`;panel.querySelector('button').onclick=()=>{document.getElementById('country-dialog').close();goCourtyard(open);};content.prepend(panel);});
 tray();return {open};
}
